-- Dispute Hub SQL practice database (simulated data)

-- Runs on SQLite. See the guide for notes on PostgreSQL, MySQL and SQL Server.

CREATE TABLE merchants (
  merchant_id TEXT PRIMARY KEY,
  merchant_name TEXT NOT NULL,
  segment TEXT NOT NULL,
  region TEXT NOT NULL,
  rollout_wave TEXT NOT NULL,
  portal_enabled_date TEXT,
  annual_revenue_usd INTEGER
);
CREATE TABLE reason_codes (
  reason_code TEXT PRIMARY KEY,
  category TEXT NOT NULL,
  description TEXT NOT NULL,
  response_window_days INTEGER NOT NULL
);
CREATE TABLE disputes (
  dispute_id TEXT PRIMARY KEY,
  merchant_id TEXT NOT NULL,
  card_network TEXT NOT NULL,
  reason_code TEXT NOT NULL,
  dispute_amount REAL NOT NULL,
  received_at TEXT NOT NULL,
  response_due_at TEXT NOT NULL,
  responded_at TEXT,
  response_channel TEXT,
  internal_status TEXT NOT NULL,
  outcome TEXT,
  recovered_amount REAL,
  closed_at TEXT
);
CREATE TABLE status_events (
  event_id INTEGER PRIMARY KEY,
  dispute_id TEXT NOT NULL,
  processor_status TEXT NOT NULL,
  internal_status TEXT NOT NULL,
  processor_event_at TEXT NOT NULL,
  hub_updated_at TEXT NOT NULL
);
CREATE TABLE portal_users (
  user_id TEXT PRIMARY KEY,
  merchant_id TEXT NOT NULL,
  role TEXT NOT NULL,
  invited_at TEXT NOT NULL,
  first_login_at TEXT
);
CREATE TABLE evidence_files (
  file_id INTEGER PRIMARY KEY,
  dispute_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  file_type TEXT NOT NULL,
  file_size_kb INTEGER NOT NULL,
  uploaded_at TEXT NOT NULL,
  redaction_status TEXT NOT NULL
);
CREATE TABLE analytics_events (
  event_id INTEGER PRIMARY KEY,
  user_id TEXT NOT NULL,
  event_name TEXT NOT NULL,
  event_at TEXT NOT NULL,
  dispute_id TEXT
);
CREATE TABLE analysts (
  analyst_id TEXT PRIMARY KEY,
  analyst_name TEXT NOT NULL,
  team TEXT NOT NULL
);
CREATE TABLE ops_work_items (
  work_item_id INTEGER PRIMARY KEY,
  dispute_id TEXT NOT NULL,
  analyst_id TEXT NOT NULL,
  queue_reason TEXT NOT NULL,
  assigned_at TEXT NOT NULL,
  resolved_at TEXT
);
CREATE TABLE settlements (
  settlement_id INTEGER PRIMARY KEY,
  merchant_id TEXT NOT NULL,
  payout_date TEXT NOT NULL,
  gross_sales REAL NOT NULL,
  fees REAL NOT NULL,
  chargeback_debits REAL NOT NULL,
  reversals REAL NOT NULL,
  net_payout REAL NOT NULL
);
CREATE TABLE ledger (
  ledger_id INTEGER PRIMARY KEY,
  merchant_id TEXT NOT NULL,
  payout_date TEXT NOT NULL,
  ledger_amount REAL NOT NULL
);
CREATE TABLE servicing_contacts (
  contact_id INTEGER PRIMARY KEY,
  merchant_id TEXT NOT NULL,
  contact_at TEXT NOT NULL,
  reason TEXT NOT NULL,
  channel TEXT NOT NULL
);

